-- ── 데모 접근 부여: 이메일의 프로필을 admin으로 승격(없으면 생성)하고 시드 행사 전부에 pm으로 배정
create or replace function app.grant_demo_access(p_email text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  v_id := app.promote_admin(p_email);
  select p.id, v_id, 'pm' from projects p where p.id in ('465f726d-4c59-6f09-7c68-2ba9f00b55f0', '912534d4-da13-3935-c4b6-5476c5a9f8f2', '3f364e09-c9a8-22bf-41a6-526f777747bb', '58841b3f-3d08-680b-dd59-b7848bcf4eef', '72f9aee7-09db-0a72-47e0-dd39e17ac70e', '3cb22b2f-2627-dd34-9401-62690c00f13c', '98a414d6-fbcc-45c6-af2a-6bd422643a00', '4863fa83-7430-dc63-d379-609f722cc57c')
  on conflict (project_id, user_id) do nothing;
  return v_id;
